import { type ReactElement } from 'react';
import { type FieldWrapperProps } from '@types/divi__modal';
import { type PageSettings } from '@divi/types';
export type PageSettingsFieldContainerProps = Omit<PageSettingsFieldProps, 'onChangeCallback' | 'settings'>;
export type PageSettingsFieldProps = Partial<FieldWrapperProps> & {
    name: keyof PageSettings.Store.State;
    onChangeCallback: (params: PageSettingsOnChangeParams) => void;
    children: ReactElement;
    defaultValue?: string;
    value?: string;
    visible?: boolean;
};
export type PageSettingsOnChangeParams = {
    inputValue?: string;
    name?: string;
};
